CREATE COLUMN TABLE "TEST_AP"."OLGT" ("UnitCode" SMALLINT CS_INT NOT NULL , "UnitDisply" NVARCHAR(2) NOT NULL , "UnitName" NVARCHAR(20) NOT NULL , "VolDisply" NVARCHAR(3), "SizeInMM" DECIMAL(21,6) CS_FIXED, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("UnitCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OLGT_DISPLAY" ON "TEST_AP"."OLGT" ( "UnitDisply" ASC );
CREATE UNIQUE INDEX "OLGT_UNIT_NAME" ON "TEST_AP"."OLGT" ( "UnitName" ASC );
CREATE INDEX "OLGT_VOLUME" ON "TEST_AP"."OLGT" ( "VolDisply" ASC )